export type CopyKeyName = (typeof ROWS)[number][0];

export const COPY: CopyKey[] = ROWS.map(([key, english, filipino, waray]) =>
  CopyKey.parse({ key, english, filipino, waray }),
);

export const COPY_BY_KEY = new Map(COPY.map((row) => [row.key, row]));

